class Student:
    def __init__(self, name, grade):
        self.name = name
        self.grade = grade

    def introduce(self):
        return f"Hi, I'm {self.name}, grade {self.grade}."

class GraduateStudent(Student):
    def __init__(self, name, grade, thesis_topic):
        super().__init__(name, grade)
        self.thesis_topic = thesis_topic

    def introduce(self):
        return f"Hi, I'm {self.name}, grade {self.grade}. My thesis is on {self.thesis_topic}."

gs = GraduateStudent("Diana", 12, "AI in Healthcare")
print(gs.introduce())
